def compute(vars):
    total_goodwill = vars["v1"]
    bolts_goodwill = vars["v2"]
    goodwill_excluding_bolts = total_goodwill - bolts_goodwill

    return {
        "value": goodwill_excluding_bolts,
        "trace": {
            "total_goodwill": total_goodwill,
            "bolts_goodwill": bolts_goodwill,
            "goodwill_excluding_bolts": goodwill_excluding_bolts,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": "currency amount"
            }
        }
    }
